// State
        let gpuDevice = null;
        let gpuAdapter = null;
        let isBenchmarking = false;
        let benchAbort = false;
        const stabilitySamples = [];

        // DOM Elements
        const webgpuCompatBanner = document.getElementById('webgpu-compat-banner');
        const gpuVendorTitle = document.getElementById('gpu-vendor-title');
        const gpuTypeBadge = document.getElementById('gpu-type-badge');
        const gpuDescSub = document.getElementById('gpu-desc-sub');
        const webgpuSupportPill = document.getElementById('webgpu-support-pill');
        const readoutTflops = document.getElementById('readout-tflops');
        const readoutGflopsSub = document.getElementById('readout-gflops-sub');
        const benchProgressBar = document.getElementById('bench-progress-bar');
        const liveStage = document.getElementById('live-stage');
        const liveBandwidth = document.getElementById('live-bandwidth');
        const liveThrottle = document.getElementById('live-throttle');
        const liveTier = document.getElementById('live-tier');
        const benchArena = document.getElementById('bench-arena');
        const startBenchBtn = document.getElementById('start-bench-btn');

        // WGSL Matrix Multiplication Compute Shader
        const WGSL_MATMUL_SHADER = `
        @group(0) @binding(0) var<storage, read> matrixA : array<f32>;
        @group(0) @binding(1) var<storage, read> matrixB : array<f32>;
        @group(0) @binding(2) var<storage, read_write> matrixC : array<f32>;
        @group(0) @binding(3) var<uniform> dim : u32;

        @compute @workgroup_size(16, 16)
        fn main(@builtin(global_invocation_id) global_id : vec3<u32>) {
            let row = global_id.x;
            let col = global_id.y;
            let n = dim;

            if (row >= n || col >= n) {
                return;
            }

            var sum = 0.0;
            for (var i = 0u; i < n; i = i + 1u) {
                sum = sum + matrixA[row * n + i] * matrixB[i * n + col];
            }
            matrixC[row * n + col] = sum;
        }
        `;

        async function probeWebGpuHardware() {
            if (!navigator.gpu) {
                showWebGpuFallback("WebGPU API Not Detected. Please test in Chrome 113+, Edge 113+, or Safari 18+.");
                return;
            }

            try {
                gpuAdapter = await navigator.gpu.requestAdapter({ powerPreference: "high-performance" });
                if (!gpuAdapter) {
                    showWebGpuFallback("No High-Performance WebGPU Adapter Available.");
                    return;
                }

                gpuDevice = await gpuAdapter.requestDevice();

                const info = await gpuAdapter.requestAdapterInfo ? await gpuAdapter.requestAdapterInfo() : {};
                const vendor = info.vendor || "Standard GPU Vendor";
                const arch = info.architecture || "Modern GPU Architecture";
                const device = info.device || info.description || "WebGPU Direct Execution Adapter";
                const isDiscrete = gpuAdapter.isFallbackAdapter === false;

                gpuVendorTitle.innerText = `${vendor.toUpperCase()} - ${device}`;
                gpuTypeBadge.innerText = isDiscrete ? "Dedicated / Unified GPU" : "Software / Fallback";
                gpuTypeBadge.className = isDiscrete ? "px-2 py-0.5 rounded text-[10px] font-bold bg-purple-100 text-purple-700" : "px-2 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-700";
                gpuDescSub.innerText = `Architecture: ${arch} | WebGPU Compute WGSL Ready`;

                webgpuSupportPill.className = "px-3 py-1 rounded-full text-xs font-bold bg-emerald-50 text-emerald-700 border border-emerald-200 flex items-center gap-1.5";
                webgpuSupportPill.innerHTML = '<span class="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span> WebGPU Active';

                const asideStatus = document.getElementById('aside-adapter-status');
                if (asideStatus) {
                    asideStatus.innerText = 'ONLINE';
                    asideStatus.className = 'text-emerald-600 font-bold uppercase text-[10px]';
                }

                document.getElementById('spec-adapter').innerText = device;
                document.getElementById('spec-vendor').innerText = vendor;

                const limits = gpuDevice.limits;
                if (limits) {
                    const maxBufMB = (limits.maxStorageBufferBindingSize / (1024 * 1024)).toFixed(0);
                    document.getElementById('spec-buffer-size').innerText = `${maxBufMB} MB`;
                    document.getElementById('spec-invocations').innerText = limits.maxComputeWorkgroupInvocations.toLocaleString();
                }

            } catch (err) {
                showWebGpuFallback(`WebGPU Initialization Error: ${err.message}`);
            }
        }

        function showWebGpuFallback(msg) {
            gpuVendorTitle.innerText = "WebGPU Disabled or Unsupported";
            gpuTypeBadge.innerText = "Compatibility Mode";
            gpuTypeBadge.className = "px-2 py-0.5 rounded text-[10px] font-bold bg-rose-100 text-rose-700";
            gpuDescSub.innerText = msg;
            webgpuSupportPill.className = "px-3 py-1 rounded-full text-xs font-bold bg-rose-50 text-rose-700 border border-rose-200 flex items-center gap-1.5";
            webgpuSupportPill.innerHTML = '<span class="w-2 h-2 rounded-full bg-rose-500"></span> WebGPU Unavailable';
            startBenchBtn.disabled = true;
            startBenchBtn.className = "w-full py-2.5 px-4 rounded-xl bg-slate-300 text-slate-500 font-bold text-xs cursor-not-allowed";
        }

        async function startWebGpuBenchmark() {
            if (!gpuDevice || isBenchmarking) return;

            isBenchmarking = true;
            benchAbort = false;
            stabilitySamples.length = 0;
            startBenchBtn.disabled = true;
            benchArena.classList.add('bench-running');

            const profile = document.getElementById('workload-profile').value;
            const matrixN = Number(document.getElementById('matrix-size-select').value) || 1024;
            const targetDurationSeconds = profile === 'sustained-thermal' ? 30 : 5;

            liveStage.innerText = `Compiling WGSL Matrix Shader (${matrixN}×${matrixN})...`;
            benchProgressBar.style.width = '0%';

            try {
                const shaderModule = gpuDevice.createShaderModule({ code: WGSL_MATMUL_SHADER });
                const computePipeline = gpuDevice.createComputePipeline({
                    layout: 'auto',
                    compute: { module: shaderModule, entryPoint: 'main' }
                });

                const elementCount = matrixN * matrixN;
                const byteSize = elementCount * 4;

                const initialData = new Float32Array(elementCount);
                for (let i = 0; i < elementCount; i++) {
                    initialData[i] = (i % 100) * 0.01;
                }

                const bufferA = gpuDevice.createBuffer({
                    size: byteSize,
                    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
                    mappedAtCreation: true
                });
                new Float32Array(bufferA.getMappedRange()).set(initialData);
                bufferA.unmap();

                const bufferB = gpuDevice.createBuffer({
                    size: byteSize,
                    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
                    mappedAtCreation: true
                });
                new Float32Array(bufferB.getMappedRange()).set(initialData);
                bufferB.unmap();

                const bufferC = gpuDevice.createBuffer({
                    size: byteSize,
                    usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC
                });

                const uniformBuffer = gpuDevice.createBuffer({
                    size: 4,
                    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
                });
                gpuDevice.queue.writeBuffer(uniformBuffer, 0, new Uint32Array([matrixN]));

                const bindGroup = gpuDevice.createBindGroup({
                    layout: computePipeline.getBindGroupLayout(0),
                    entries: [
                        { binding: 0, resource: { buffer: bufferA } },
                        { binding: 1, resource: { buffer: bufferB } },
                        { binding: 2, resource: { buffer: bufferC } },
                        { binding: 3, resource: { buffer: uniformBuffer } }
                    ]
                });

                const flopsPerPass = 2 * Math.pow(matrixN, 3);
                let completedPasses = 0;
                const startTime = performance.now();
                const endTime = startTime + (targetDurationSeconds * 1000);

                let initialBurstFlops = 0;
                let lowestSustainedFlops = Infinity;

                liveStage.innerText = "Dispatching Compute Kernels...";

                const workgroupsX = Math.ceil(matrixN / 16);
                const workgroupsY = Math.ceil(matrixN / 16);

                while (performance.now() < endTime && !benchAbort) {
                    const commandEncoder = gpuDevice.createCommandEncoder();
                    const passEncoder = commandEncoder.beginComputePass();
                    passEncoder.setPipeline(computePipeline);
                    passEncoder.setBindGroup(0, bindGroup);

                    const batchSize = matrixN >= 2048 ? 1 : 4;
                    for (let b = 0; b < batchSize; b++) {
                        passEncoder.dispatchWorkgroups(workgroupsX, workgroupsY);
                    }
                    passEncoder.end();
                    gpuDevice.queue.submit([commandEncoder.finish()]);

                    await gpuDevice.queue.onSubmittedWorkDone();
                    completedPasses += batchSize;

                    const elapsedMs = performance.now() - startTime;
                    const elapsedSec = elapsedMs / 1000;
                    const currentTotalFlops = completedPasses * flopsPerPass;
                    const currentTflops = (currentTotalFlops / 1e12) / elapsedSec;
                    const currentGflops = currentTflops * 1000;

                    readoutTflops.innerText = currentTflops.toFixed(2);
                    readoutGflopsSub.innerText = `${currentGflops.toFixed(1)} GFLOPs (${completedPasses.toLocaleString()} passes)`;

                    const pct = Math.min(100, (elapsedMs / (targetDurationSeconds * 1000)) * 100);
                    benchProgressBar.style.width = `${pct.toFixed(1)}%`;

                    const totalBytesTransferred = completedPasses * (byteSize * 3);
                    const bandwidthGBs = (totalBytesTransferred / (1024 * 1024 * 1024)) / elapsedSec;
                    liveBandwidth.innerText = `${bandwidthGBs.toFixed(1)} GB/s`;

                    if (elapsedSec > 0.5) {
                        stabilitySamples.push({ time: elapsedSec, tflops: currentTflops });
                        if (initialBurstFlops === 0 && elapsedSec >= 1.5) {
                            initialBurstFlops = currentTflops;
                        }
                        if (currentTflops < lowestSustainedFlops && elapsedSec > 2.0) {
                            lowestSustainedFlops = currentTflops;
                        }
                    }

                    updateStabilityChart();
                }

                const finalElapsedSec = (performance.now() - startTime) / 1000;
                const finalTflops = ((completedPasses * flopsPerPass) / 1e12) / finalElapsedSec;
                readoutTflops.innerText = finalTflops.toFixed(2);
                benchProgressBar.style.width = '100%';
                liveStage.innerText = "Benchmark Concluded";

                if (initialBurstFlops > 0 && lowestSustainedFlops !== Infinity && initialBurstFlops > lowestSustainedFlops) {
                    const dropPct = ((initialBurstFlops - lowestSustainedFlops) / initialBurstFlops) * 100;
                    liveThrottle.innerText = `-${dropPct.toFixed(1)}%`;
                    liveThrottle.className = dropPct > 15 ? "text-xl font-black text-rose-600 mono-num" : "text-xl font-black text-amber-600 mono-num";
                } else {
                    liveThrottle.innerText = "0.0%";
                    liveThrottle.className = "text-xl font-black text-emerald-600 mono-num";
                }

                assignHardwareTier(finalTflops);

            } catch (err) {
                liveStage.innerText = `Compute Error: ${err.message}`;
            } finally {
                isBenchmarking = false;
                startBenchBtn.disabled = false;
                benchArena.classList.remove('bench-running');
            }
        }

        function assignHardwareTier(tflops) {
            let tier = '';
            let color = '';
            if (tflops >= 12.0) {
                tier = 'Ultra Flagship (>12 TFLOPs)';
                color = 'text-purple-600';
            } else if (tflops >= 6.0) {
                tier = 'High-Performance (6-12 TFLOPs)';
                color = 'text-indigo-600';
            } else if (tflops >= 2.5) {
                tier = 'Mid-Range (2.5-6 TFLOPs)';
                color = 'text-sky-600';
            } else {
                tier = 'Integrated Mobile (<2.5 TFLOPs)';
                color = 'text-slate-700';
            }

            liveTier.innerText = tier;
            liveTier.className = `text-xs font-black ${color} block mt-1 truncate`;
        }

        function updateStabilityChart() {
            if (stabilitySamples.length < 2) return;
            document.getElementById('chart-empty-msg').style.display = 'none';
            document.getElementById('chart-samples-label').innerText = `${stabilitySamples.length} Samples`;

            const maxTflops = Math.max(...stabilitySamples.map(s => s.tflops), 1.0) * 1.15;
            const maxTime = Math.max(...stabilitySamples.map(s => s.time), 1.0);

            const points = stabilitySamples.map(s => {
                const x = (s.time / maxTime) * 800;
                const y = 150 - ((s.tflops / maxTflops) * 130 + 10);
                return `${x.toFixed(1)},${y.toFixed(1)}`;
            });

            const pathStr = `M ${points.join(' L ')}`;
            const areaStr = `M ${points[0]} L ${points.join(' L ')} L 800,150 L 0,150 Z`;

            document.getElementById('throttle-path').setAttribute('d', pathStr);
            document.getElementById('throttle-area').setAttribute('d', areaStr);
        }

        function copyHardwareDetails() {
            const specAdapter = document.getElementById('spec-adapter').innerText;
            const specVendor = document.getElementById('spec-vendor').innerText;
            const tflops = readoutTflops.innerText;

            const text = `=== WebGPU Compute Benchmark Report ===\n` +
                `GPU: ${specAdapter}\n` +
                `Vendor: ${specVendor}\n` +
                `Measured FP32 Compute: ${tflops} TFLOPs\n` +
                `Hardware Tier: ${liveTier.innerText}\n` +
                `Tool: https://toolkitgen.com/tool/webgpu_compute_flops_benchmark`;

            if (navigator.clipboard) {
                navigator.clipboard.writeText(text).then(() => alert("Hardware specs copied to clipboard!"));
            } else {
                prompt("Copy specs:", text);
            }
        }

        window.addEventListener('DOMContentLoaded', probeWebGpuHardware);
